let decoded: ReadonlyMap<string, WorldOutline> | null = null

/**
 * Turns an encoded payload into outlines keyed by ISO alpha-2.
 *
 * Exported because there are two payloads in this shape and only one of them is
 * bundled: `./countries` fetches the finer 1:50m cut as a static asset and
 * decodes it here rather than growing a second parser that could drift from
 * this one. `scale` is the payload's quantisation grid, which the finer asset
 * states in its own manifest.
 *
 * Tolerant of a stray separator — an empty entry, or one with no colon, is
 * skipped rather than producing a country called `''` — because one of the two
 * payloads arrives over the network.
 */
export function decodeOutlines(
  encoded: string,
  scale: number = SCALE,
): ReadonlyMap<string, WorldOutline> {
  const out = new Map<string, WorldOutline>()
  for (const entry of encoded.split('|')) {
    const split = entry.indexOf(':')
    if (split <= 0) continue
    const iso = entry.slice(0, split)
    const rings: Array<WorldRing> = []
    for (const encodedRing of entry.slice(split + 1).split(';')) {
      const deltas = encodedRing.split(',')
      const ring: Array<readonly [number, number]> = []
      let lng = 0
      let lat = 0
      for (let index = 0; index + 1 < deltas.length; index += 2) {
        lng += Number(deltas[index])
        lat += Number(deltas[index + 1])
        ring.push([lng / scale, lat / scale])
      }
      rings.push(ring)
    }
    out.set(iso, rings)
  }
  return out
}

/**
 * Every country's outline, keyed by ISO 3166-1 alpha-2.
 *
 * Decoded on first call and cached for the life of the process, because the
 * result is deeply immutable and every caller wants the same thing.
 */
export function worldOutlines(): ReadonlyMap<string, WorldOutline> {
  decoded ??= decodeOutlines(ENCODED)
  return decoded
}

/** The outlines of one country, or an empty list for a code we do not carry. */
export function outlineFor(countryCode: string): WorldOutline {
  return worldOutlines().get(countryCode.toUpperCase()) ?? []
}

/** How many countries the bundled geometry can draw. Used by tests. */
export function worldOutlineCount(): number {
  return worldOutlines().size
}

/* -------------------------------------------------------------------------------------------------
 * Projection
 * ---------------------------------------------------------------------------------------------- */

/** Turns a degree pair into drawing units. Both axes point the usual SVG way. */
export type Projection = (lng: number, lat: number) => readonly [number, number]

/** A ring's degree extent, used to skip geometry that cannot be on screen. */
export interface DegreeBox {
  readonly minLng: number
  readonly maxLng: number
  readonly minLat: number
  readonly maxLat: number
}

function boxOf(ring: WorldRing): DegreeBox {
  let minLng = Infinity
  let maxLng = -Infinity
  let minLat = Infinity
  let maxLat = -Infinity
  for (const [lng, lat] of ring) {
    if (lng < minLng) minLng = lng
    if (lng > maxLng) maxLng = lng
    if (lat < minLat) minLat = lat
    if (lat > maxLat) maxLat = lat
  }
  return { minLng, maxLng, minLat, maxLat }
}

function overlaps(a: DegreeBox, b: DegreeBox): boolean {
  return (
    a.minLng <= b.maxLng &&
    a.maxLng >= b.minLng &&
    a.minLat <= b.maxLat &&
    a.maxLat >= b.minLat
  )
}

/**
 * One SVG `d` string for a set of rings.
 *
 * Coordinates are rounded to `precision` decimals — at a tenth of a drawing
 * unit the rounding is invisible and it keeps a world map's path data, which is
 * inlined into the server-rendered document, roughly a third smaller.
 */
export function ringsToPath(
  rings: ReadonlyArray<WorldRing>,
  project: Projection,
  precision = 1,
): string {
  let path = ''
  for (const ring of rings) {
    if (ring.length < 3) continue
    let previousX: number | null = null
    let previousY: number | null = null
    let drawn = 0
    let segment = ''
    for (const [lng, lat] of ring) {
      const [rawX, rawY] = project(lng, lat)
      const x = Number(rawX.toFixed(precision))
      const y = Number(rawY.toFixed(precision))
      // Quantisation collapses neighbouring vertices; emitting both would only
      // grow the string.
      if (x === previousX && y === previousY) continue
      segment += `${drawn === 0 ? 'M' : 'L'}${x} ${y}`
      previousX = x
      previousY = y
      drawn += 1
    }
    if (drawn >= 3) path += `${segment}Z`
  }
  return path
}

/**
 * The land inside a degree window, as a single path.
 *
 * Rings whose extent cannot reach the window are dropped before projection, so a
 * city-scale drawing pays for one country rather than 175.
 */
export function landPath(
  window: DegreeBox,
  project: Projection,
  precision = 1,
): string {
  const rings: Array<WorldRing> = []
  for (const outline of worldOutlines().values()) {
    for (const ring of outline) {
      if (overlaps(boxOf(ring), window)) rings.push(ring)
    }
  }
  return ringsToPath(rings, project, precision)
}
